CREATE TEMPORARY TABLE tc_tl_actual AS SELECT 'club' kind, c.club_code business_key, v.club_name val, v.budget_eur amount,
 v.valid_from,v.valid_to,v.tx_from,v.tx_to,LEFT(r.reason,3) ref, v.version_id, v.tx_id,c.club_id
 FROM club_version v JOIN club c USING(club_id) JOIN tx_registry r USING(tx_id)
UNION ALL
SELECT 'contract',CONCAT(p.player_code,'/',c.club_code),v.agreement_kind,v.salary_eur,
 v.valid_from,v.valid_to,v.tx_from,v.tx_to,LEFT(r.reason,3),v.version_id,v.tx_id,c.club_id
 FROM contract_version v JOIN contract a USING(contract_id) JOIN player p USING(player_id)
 JOIN club c USING(club_id) JOIN tx_registry r USING(tx_id)
UNION ALL
SELECT 'role',c.club_code,h.coach_code,0,v.valid_from,v.valid_to,v.tx_from,v.tx_to,
 LEFT(r.reason,3),v.version_id,v.tx_id,c.club_id
 FROM head_coach_role_version v JOIN head_coach_role a USING(role_id)
 JOIN club c USING(club_id) JOIN coach h USING(coach_id) JOIN tx_registry r USING(tx_id);

CALL tc_tl_assert('38 exact registries; 53 exact tags', ((SELECT COUNT(*) FROM tx_registry)=38 AND (SELECT COUNT(*) FROM tx_event_tag)=53));

CALL tc_tl_assert('T01 exact UTC, reason prefix, author and tag set', ((SELECT COUNT(*) FROM tx_registry r WHERE BINARY LEFT(r.reason,3)=BINARY 'T01' AND r.tx_time='2025-07-01 09:00:00.000000' AND BINARY r.author=BINARY 'Boar Victor — dataset fictiv' AND (SELECT GROUP_CONCAT(e.event_code ORDER BY e.event_code SEPARATOR ',') FROM tx_event_tag e WHERE e.tx_id=r.tx_id)='E1')=1));

CALL tc_tl_assert('T02 exact UTC, reason prefix, author and tag set', ((SELECT COUNT(*) FROM tx_registry r WHERE BINARY LEFT(r.reason,3)=BINARY 'T02' AND r.tx_time='2025-09-10 14:00:00.000000' AND BINARY r.author=BINARY 'Boar Victor — dataset fictiv' AND (SELECT GROUP_CONCAT(e.event_code ORDER BY e.event_code SEPARATOR ',') FROM tx_event_tag e WHERE e.tx_id=r.tx_id)='E3')=1));

