CREATE TEMPORARY TABLE tc_tl_before_club_version AS SELECT * FROM club_version;

CREATE TEMPORARY TABLE tc_tl_before_contract_version AS SELECT * FROM contract_version;

CREATE TEMPORARY TABLE tc_tl_before_head_coach_role_version AS SELECT * FROM head_coach_role_version;

CREATE TEMPORARY TABLE tc_tl_before_tx_registry AS SELECT * FROM tx_registry;

CREATE TEMPORARY TABLE tc_tl_before_tx_event_tag AS SELECT * FROM tx_event_tag;

CREATE TEMPORARY TABLE tc_tl_before_query_params AS SELECT * FROM query_params;

DELIMITER $$
CREATE PROCEDURE tc_tl_negative(IN case_name VARCHAR(160), IN sql_text TEXT, IN expected_message VARCHAR(128))
BEGIN
 DECLARE got_errno INT DEFAULT 0;
 DECLARE got_message TEXT DEFAULT '';
 DECLARE prepared_ok BOOLEAN DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  ROLLBACK;
  IF prepared_ok THEN DEALLOCATE PREPARE tc_tl_stmt; END IF;
  SET @sim_now=NULL,@write_tx_id=NULL,@tc_tl_sql=NULL;
  RESIGNAL;
 END;
 START TRANSACTION;
 SET @tc_tl_sql=sql_text;
 PREPARE tc_tl_stmt FROM @tc_tl_sql;
 SET prepared_ok=TRUE;
 BEGIN
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
   GET DIAGNOSTICS CONDITION 1 got_errno=MYSQL_ERRNO,got_message=MESSAGE_TEXT;
  EXECUTE tc_tl_stmt;
 END;
 DEALLOCATE PREPARE tc_tl_stmt;
 SET prepared_ok=FALSE;
 ROLLBACK;
 SET @tc_tl_sql=NULL;
 CALL tc_tl_assert(case_name,got_errno=1644 AND BINARY got_message=BINARY expected_message);
END$$
DELIMITER ;

CALL tc_tl_negative('club_version open UPDATE','UPDATE club_version SET budget_eur=budget_eur+1 WHERE tx_to = ''9999-12-31 23:59:59.999999'' ORDER BY version_id LIMIT 1','TC_COLUMNS: only tx_to may change');

